 trainer_id INTEGER,
 location TEXT,
 notes TEXT,
 source TEXT,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL
, delivery_mode TEXT, organization_id INTEGER, agency_id INTEGER, prestation_type TEXT NOT NULL DEFAULT 'FORMATION', use_attendance INTEGER NOT NULL DEFAULT 1, use_quality_hot INTEGER NOT NULL DEFAULT 0, use_quality_cold INTEGER NOT NULL DEFAULT 0, use_trainer_feedback INTEGER NOT NULL DEFAULT 0, archived_at TEXT, start_date TEXT, end_date TEXT, quality_cold_due_date TEXT, client_admin_email TEXT, client_training_email TEXT, client_quality_email TEXT, client_billing_email TEXT, client_other_email TEXT, final_bundle_due_at TEXT, final_bundle_generated_at TEXT, final_bundle_path TEXT, portal_expires_at TEXT, portal_warning_sent_at TEXT, quality_contact_name TEXT, training_contact_name TEXT, training_contact_phone TEXT, transmit_final_bundle INTEGER NOT NULL DEFAULT 0, send_final_to_quality INTEGER NOT NULL DEFAULT 1, send_final_to_training INTEGER NOT NULL DEFAULT 1, final_other_first_name TEXT, final_other_last_name TEXT, final_other_email TEXT);
