CREATE TABLE service_competency_criteria (
 id INTEGER PRIMARY KEY AUTOINCREMENT, service_id INTEGER NOT NULL, criterion_code TEXT NOT NULL,
 category TEXT NOT NULL, label TEXT NOT NULL, description TEXT, required INTEGER NOT NULL DEFAULT 0,
 weight REAL, minimum_level INTEGER NOT NULL DEFAULT 0, accepted_evidence_json TEXT, validity_months INTEGER,
 active INTEGER NOT NULL DEFAULT 1, current_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, source_kind TEXT, source_reference TEXT,
 UNIQUE(service_id,criterion_code),
 CHECK(category IN ('METIER_TECHNIQUE','PEDAGOGIQUE','ACCOMPAGNEMENT_COACHING','COMPORTEMENTAL','REGLEMENTAIRE')),
 CHECK(minimum_level BETWEEN 0 AND 4), CHECK(required IN (0,1)), CHECK(active IN (0,1)),
 FOREIGN KEY(service_id) REFERENCES service_catalog(id) ON DELETE RESTRICT
);
INSERT INTO "service_competency_criteria" VALUES(1,1,'BC_CADRE_FINALITE','REGLEMENTAIRE','Maîtriser le cadre, la finalité et les limites du bilan de compétences','Savoir expliquer le dispositif, son objectif, la confidentialité, les responsabilités et les limites de l’accompagnement.',1,NULL,3,'["FORMATION", "CERTIFICATION", "ATTESTATION", "EXPERIENCE", "ENTRETIEN", "DOCUMENT"]',NULL,1,1,'2026-10-19T09:26:54.659238+00:00','2026-10-19T09:26:54.659238+00:00','ADAPTATION_CLARTE360','CDC correctif V1.1 / adaptation métier Clarté360 J15');
INSERT INTO "service_competency_criteria" VALUES(2,1,'BC_ANALYSE_DEMANDE','ACCOMPAGNEMENT_COACHING','Analyser la demande et clarifier les objectifs du bénéficiaire','Conduire l’analyse de la demande, reformuler les attentes et poser un cadre de travail individualisé.',1,NULL,3,'["CV", "EXPERIENCE", "MISSION", "REFERENCE", "ENTRETIEN", "DOCUMENT"]',NULL,1,1,'2026-10-19T09:26:54.659238+00:00','2026-10-19T09:26:54.659238+00:00','ADAPTATION_CLARTE360','CDC correctif V1.1 / adaptation métier Clarté360 J15');
INSERT INTO "service_competency_criteria" VALUES(3,1,'BC_CONDUITE_PHASES','METIER_TECHNIQUE','Conduire un bilan de compétences de manière structurée','Maîtriser un déroulé cohérent de l’accueil à la conclusion, avec investigation, synthèse et plan d’action.',1,NULL,3,'["FORMATION", "ATTESTATION", "EXPERIENCE", "MISSION", "REFERENCE", "ENTRETIEN", "DOCUMENT"]',NULL,1,1,'2026-10-19T09:26:54.659238+00:00','2026-10-19T09:26:54.659238+00:00','ADAPTATION_CLARTE360','CDC correctif V1.1 / adaptation métier Clarté360 J15');
INSERT INTO "service_competency_criteria" VALUES(4,1,'BC_EXPLORATION','ACCOMPAGNEMENT_COACHING','Explorer compétences, motivations, intérêts, valeurs et contraintes','Utiliser l’entretien et des outils adaptés sans enfermer la personne dans une typologie.',1,NULL,3,'["CV", "EXPERIENCE", "MISSION", "REFERENCE", "ENTRETIEN", "DOCUMENT"]',NULL,1,1,'2026-10-19T09:26:54.659238+00:00','2026-10-19T09:26:54.659238+00:00','ADAPTATION_CLARTE360','CDC correctif V1.1 / adaptation métier Clarté360 J15');
INSERT INTO "service_competency_criteria" VALUES(5,1,'BC_PROJET_VERIFICATION','METIER_TECHNIQUE','Accompagner l’élaboration et la vérification du projet professionnel','Aider à formuler des hypothèses, les confronter à la réalité et construire un plan d’action réaliste.',1,NULL,3,'["CV", "EXPERIENCE", "MISSION", "REFERENCE", "ENTRETIEN", "DOCUMENT"]',NULL,1,1,'2026-10-19T09:26:54.659238+00:00','2026-10-19T09:26:54.659238+00:00','ADAPTATION_CLARTE360','CDC correctif V1.1 / adaptation métier Clarté360 J15');
INSERT INTO "service_competency_criteria" VALUES(6,1,'BC_POSTURE_AUTONOMIE','COMPORTEMENTAL','Adopter une posture favorisant l’autonomie et la décision du bénéficiaire','Questionner, reformuler et faire réfléchir sans décider à la place de la personne.',1,NULL,3,'["EXPERIENCE", "MISSION", "REFERENCE", "ENTRETIEN"]',NULL,1,1,'2026-10-19T09:26:54.659238+00:00','2026-10-19T09:26:54.659238+00:00','ADAPTATION_CLARTE360','CDC correctif V1.1 / adaptation métier Clarté360 J15');
INSERT INTO "service_competency_criteria" VALUES(7,1,'BC_SYNTHESE','METIER_TECHNIQUE','Produire une synthèse utile, fidèle et exploitable','Structurer une synthèse qui reprend les éléments utiles au bénéficiaire et son plan d’action, sans inventer de conclusions.',1,NULL,3,'["EXPERIENCE", "MISSION", "REFERENCE", "DOCUMENT", "ENTRETIEN"]',NULL,1,1,'2026-10-19T09:26:54.659238+00:00','2026-10-19T09:26:54.659238+00:00','ADAPTATION_CLARTE360','CDC correctif V1.1 / adaptation métier Clarté360 J15');
INSERT INTO "service_competency_criteria" VALUES(8,1,'BC_CONFIDENTIALITE','REGLEMENTAIRE','Garantir confidentialité, consentement et traçabilité du dossier','Appliquer les règles internes de confidentialité, de consentement, de droits d’accès et de conservation des informations.',1,NULL,3,'["FORMATION", "ATTESTATION", "EXPERIENCE", "ENTRETIEN", "DOCUMENT"]',NULL,1,1,'2026-10-19T09:26:54.659238+00:00','2026-10-19T09:26:54.659238+00:00','ADAPTATION_CLARTE360','CDC correctif V1.1 / adaptation métier Clarté360 J15');
